head.script:
scwin.gVar = {
    "cReadOnlyClass" : "",
    "cReadOnly" : "",
    "bReadOnly" : false,
}



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[secret > P > readOnlyClass]<br/>Secret 컴포넌트가 읽기 전용(readonly) 상태일때 적용할 CSS 클래스를 설정합니다.",
    "validation" : [
        "CSS 파일이나 style 블럭에 정의된 클래스 이름을 공백으로 구분하여 설정합니다.",
        "값을 설정하지 않으면 'w2input_readonly' 클래스가 적용됩니다.",
        "속성값을 설정하면 기본값인 'w2input_readonly' 클래스는 적용되지 않습니다.",
        "컴포넌트에 읽기 전용(readonly) 상태가 적용되면 설정한 CSS 클래스가 추가되고, 해제되면 적용된 CSS 클래스가 제거됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 정적 select1 기본값 설정 (gdl_boolean 은 코드값, 자체 값 selectbox 는 value)
    con_readOnlyClass.setValue("readOnlyClass");
    con_readOnly.setValue("1");

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 컴포넌트 있으면 삭제
    if (typeof label1 !== 'undefined') {
        label1.remove();
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="readOnlyClass 는 배경 회색, evenClass 는 둥근 모서리로 tc.css 에 정의되어 있습니다\nsetReadOnly 버튼은 누를 때마다 읽기 전용 상태가 반전되며, 반전의 기준은 재생성 시점의 readOnly 조건값입니다"', '', 'label1');

    // 조건 설정
    scwin.gVar["cReadOnlyClass"] = con_readOnlyClass.getValue();
    scwin.gVar["cReadOnly"] = con_readOnly.getText();

    // setReadOnly 반전의 기준이 되는 초기 렌더 상태
    scwin.gVar["bReadOnly"] = (scwin.gVar["cReadOnly"] === "true");

    let properties = {
        readOnlyClass : scwin.gVar["cReadOnlyClass"],
        readOnly : scwin.gVar["cReadOnly"],
    }

    let cList = $c.gcm.createCList(properties);

    // comp 생성 함수 호출
    await $c.gcm.createBasicSecret(cList);

    // 초기 렌더 시점의 class (상태 전환 전 기준선) - validation 1 ~ 4 판정 출력
    scwin.printClass("재생성 직후");
}



// 시점별 class 문자열 출력 (판정 근거)
scwin.printClass = function (strWhen) {
    let strReadOnlyClass = (scwin.gVar["cReadOnlyClass"] === "") ? "미설정" : scwin.gVar["cReadOnlyClass"];
    let strReadOnly = (scwin.gVar["cReadOnly"] === "") ? "미설정" : scwin.gVar["cReadOnly"];

    // 기본 클래스(w2input_readonly)는 배경색과 테두리를 함께 바꾸므로 두 값을 같이 출력한다
    wf_body_bottom.getObj("scwin").setReturnValue("readOnlyClass " + strReadOnlyClass + " / 초기 렌더 readOnly " + strReadOnly + " -> " + strWhen + " class : " + target1.render.className + " / bg : " + target1.getStyle("background-color") + " / border : " + target1.getStyle("border-color"));
}



// 읽기 전용 상태 전환 (readOnlyClass 의 추가/제거 발동 수단) - validation 1 ~ 4 판정 출력
scwin.btn_setReadOnly_onclick = function (e) {
    scwin.gVar["bReadOnly"] = !scwin.gVar["bReadOnly"];

    target1.setReadOnly(scwin.gVar["bReadOnly"]);

    scwin.printClass("setReadOnly(" + scwin.gVar["bReadOnly"] + ") 후");
}
